targets.query:
from(bucket: "cloudbktcp")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "ePower")
  |> filter(fn: (r) => r["eMeter"] == "VHWP")
  |> filter(fn: (r) => r["_field"] == "sumWh")
  //|> increase()
  //|> aggregateWindow(every: 5m, fn: last, offset: -1h)
 // |> duplicate(column: "_stop", as: "_time")
  //|> max()
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)
  |> increase()
  |> yield(name: "increase")

