from(bucket: "LiviusStats")
|> range(start: v.timeRangeStart, stop: v.timeRangeStop)
|> filter(fn: (r) => r["_measurement"] == "vhwp_runs_from_total")
|> group()
//it is a bit tricky, we only want 1 signal point / time
//looking at the total energy counter it should not make a big difference
//if we take the running (ok)  or off edge (info) but you get on the beginning or end assignment problems
//for now we live with that error, it is about 500 Wh over the total Range
|> filter(fn: (r) => r["_level"] == "info")
|> sort(columns: ["_time"])
|> difference()
|> rename (columns: {_value: "vhwp_sumWh"})
|> yield (name: "vhwp_sumWh")

from(bucket: "bktRP4GH")
|> range(start: v.timeRangeStart, stop: v.timeRangeStop)
|> filter(fn: (r) => r["_measurement"] == "wpgh_runs_from_total")
|> group()
//it is a bit tricky, we only want 1 signal point / time
//looking at the total energy counter it should not make a big difference
//if we take the running (ok)  or off edge (info) but you get on the beginning or end assignment problems
//for now we live with that error, it is about 500 Wh over the total Range
|> filter(fn: (r) => r["_level"] == "info")
|> sort(columns: ["_time"])
|> difference()
|> rename (columns: {_value: "ghwp_energy"})
|> yield (name: "ghwp_energy")
